#include <iostream>
#include <cstring>
#include <queue>
#include <algorithm>
using namespace std;

const int INF = 1 << 29;
const int MAXN = 500;
const int MAXE = 500000;

int head[MAXN], to[MAXE], cap[MAXE], fl[MAXE], nxt[MAXE], ecnt;
int d[MAXN], ptr[MAXN];
int n, t, sx, sy;
int temp[11][11];
bool m[11][11];

void add_edge(int a, int b, int c) {
    to[ecnt] = b;
    cap[ecnt] = c;
    fl[ecnt] = 0;
    nxt[ecnt] = head[a];
    head[a] = ecnt++;

    to[ecnt] = a;
    cap[ecnt] = 0;
    fl[ecnt] = 0;
    nxt[ecnt] = head[b];
    head[b] = ecnt++;
}

bool bfs() {
    queue<int> q;
    q.push(0);
    memset(d, -1, (n * n * 2 + 2) * sizeof(d[0]));
    d[0] = 0;
    while (!q.empty() && d[n * n * 2 + 1] == -1) {
        int v = q.front();
        q.pop();
        for (int id = head[v]; id != -1; id = nxt[id]) {
            int tov = to[id];
            if (d[tov] == -1 && fl[id] < cap[id]) {
                q.push(tov);
                d[tov] = d[v] + 1;
            }
        }
    }
    return d[n * n * 2 + 1] != -1;
}

int dfs(int v, int flow) {
    if (!flow) return 0;
    if (v == n * n * 2 + 1) return flow;
    for (int &id = ptr[v]; id != -1; id = nxt[id]) {
        int tov = to[id];
        if (d[tov] != d[v] + 1) continue;
        int pushed = dfs(tov, min(flow, cap[id] - fl[id]));
        if (pushed) {
            fl[id] += pushed;
            fl[id ^ 1] -= pushed;
            return pushed;
        }
    }
    return 0;
}

int max_flow() {
    int flow = 0;
    while (bfs()) {
        memset(ptr, -1, (n * n * 2 + 2) * sizeof(ptr[0]));
        for (int i = 0; i < n * n * 2 + 2; ++i)
            ptr[i] = head[i];
        while (int pushed = dfs(0, INF))
            flow += pushed;
    }
    return flow;
}

int way(int x1, int y1, int x2, int y2) {
    queue<pair<int, pair<int, int> > > q;
    q.push(make_pair(0, make_pair(x1, y1)));
    int h[11][11];
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            h[i][j] = INF;

    while (!q.empty()) {
        int v = q.front().first;
        int x = q.front().second.first;
        int y = q.front().second.second;
        q.pop();
        h[x][y] = v;

        if (x > 0 && m[x - 1][y] && h[x - 1][y] > v + 1) {
            bool target = (x - 1 == x2 && y == y2);
            int lim = temp[x - 1][y];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(x - 1, y)));
        }
        if (y > 0 && m[x][y - 1] && h[x][y - 1] > v + 1) {
            bool target = (x == x2 && y - 1 == y2);
            int lim = temp[x][y - 1];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(x, y - 1)));
        }
        if (x < n - 1 && m[x + 1][y] && h[x + 1][y] > v + 1) {
            bool target = (x + 1 == x2 && y == y2);
            int lim = temp[x + 1][y];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(x + 1, y)));
        }
        if (y < n - 1 && m[x][y + 1] && h[x][y + 1] > v + 1) {
            bool target = (x == x2 && y + 1 == y2);
            int lim = temp[x][y + 1];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(x, y + 1)));
        }
    }
    return h[x2][y2];
}

int main() {
    cin >> n >> t;
    memset(head, -1, sizeof(head));
    ecnt = 0;
    queue<pair<int, pair<int, int> > > q;
    char ch;
    int k = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> ch;
            temp[i][j] = t;
            if (ch == 'Z') {
                sx = i;
                sy = j;
                m[i][j] = false;
            } else if (ch == 'Y') {
                m[i][j] = false;
            } else {
                m[i][j] = true;
            }
            add_edge(0, k++, (ch == 'Z' || ch == 'Y') ? 0 : ch - '0');
        }
    }

    k = n * n + 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> ch;
            add_edge(k++, n * n * 2 + 1, (ch == 'Z' || ch == 'Y') ? 0 : ch - '0');
        }
    }

    q.push(make_pair(0, make_pair(sx, sy)));
    while (!q.empty()) {
        int v = q.front().first;
        int x = q.front().second.first;
        int y = q.front().second.second;
        q.pop();
        temp[x][y] = v;
        if (x > 0 && v + 1 < temp[x - 1][y] && m[x - 1][y])
            q.push(make_pair(v + 1, make_pair(x - 1, y)));
        if (y > 0 && v + 1 < temp[x][y - 1] && m[x][y - 1])
            q.push(make_pair(v + 1, make_pair(x, y - 1)));
        if (x < n - 1 && v + 1 < temp[x + 1][y] && m[x + 1][y])
            q.push(make_pair(v + 1, make_pair(x + 1, y)));
        if (y < n - 1 && v + 1 < temp[x][y + 1] && m[x][y + 1])
            q.push(make_pair(v + 1, make_pair(x, y + 1)));
    }

    k = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int k1 = n * n;
            ++k;
            for (int z = 0; z < n; ++z) {
                for (int w = 0; w < n; ++w) {
                    ++k1;
                    if (m[i][j] && m[z][w] && way(i, j, z, w) <= t)
                        add_edge(k, k1, INF);
                }
            }
        }
    }

    cout << max_flow();
    return 0;
}
